// Prepare: take the uploaded file (or build a sample PDF), check type/size/daily limit, build the Gemini request
const started = Date.now();
const f = $json.body || {};
const store = $getWorkflowStaticData('global');
const today = new Date().toISOString().slice(0, 10);
