const kv = [['Invoice no.', r.invoiceNumber], ['Invoice date', r.invoiceDate], ['Due date', r.dueDate], ['PO number', r.po], ['Category', r.category], ['Tax ID', r.taxId]].map(([k, v]) => `<div>${k}<b>${esc(v || '–')}</b></div>`).join('');
const rows = r.items.map((i) => `<tr><td>${esc(i.description)}</td><td class="num">${i.quantity ?? ''}</td><td class="num">${money(i.unit_price)}</td><td class="num">${money(i.amount)}</td></tr>`).join('');
// QuickBooks card: what was booked (or why not)
const qbWhen = (s) => { const d = new Date(s); return Number.isNaN(d.getTime()) ? '' : d.toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'medium', timeStyle: 'short' }) + ' UK'; };
const qbSandbox = '<p class="small muted" style="margin-top:12px">Booked in a QuickBooks Online <b>sandbox company</b>, Intuit\'s test environment (a US company in USD with multicurrency on). Visitors can\'t log in to it, so this card shows the record QuickBooks sent back.</p>';
let qbCard = '', qbLi = '';
if (qb && qb.status === 'Booked') {
  const lr = (qb.lines || []).map((l) => `<tr><td>${esc(l.d)}</td><td>${esc(l.acc)}</td><td class="num">${money(l.a)}</td></tr>`).join('');
  const fx = qb.rate && qb.currency !== qb.home ? `<div>Exchange rate<b>1 ${esc(qb.currency)} = ${esc(qb.rate)} ${esc(qb.home)}</b></div>` : '';
  qbCard = `<div class="card"><span class="st st-ok">Bill created in QuickBooks</span><h2 style="margin-top:12px">Bill ${esc(qb.billId)} for ${esc(qb.vendor)}</h2>
<div class="kv"><div>Vendor<b>${esc(qb.vendor)}</b>${qb.vendorNew ? 'created by the workflow' : 'already in QuickBooks, reused'}</div><div>Bill no.<b>${esc(qb.docNumber || '–')}</b></div><div>Bill date<b>${esc(qb.txnDate || '–')}</b></div><div>Due date<b>${esc(qb.dueDate || '–')}</b></div><div>Total<b>${money(qb.total, qb.currency)}</b></div><div>Open balance<b>${money(qb.balance, qb.currency)}</b></div>${fx}<div>Attachment<b>${qb.attachId ? 'Original PDF attached' : 'None'}</b></div></div>
${lr ? `<div style="overflow-x:auto;margin-top:14px"><table><tr><th>Bill line</th><th>Expense account</th><th class="num">Amount</th></tr>${lr}</table></div>` : ''}
${qb.note ? `<div class="warnbox">${esc(qb.note)}</div>` : ''}${qb.attachNote ? `<p class="small muted" style="margin-top:12px">${esc(qb.attachNote)}</p>` : ''}${qb.attachError ? `<p class="small muted" style="margin-top:12px">The PDF could not be attached: ${esc(qb.attachError)}</p>` : ''}
${String(r.source).startsWith('Sample') ? '<p class="small muted" style="margin-top:12px">Sample runs add a short suffix to the bill number so every visitor gets a fresh bill. For real invoices, the same supplier and invoice number already in QuickBooks is caught and not booked twice.</p>' : ''}${qbSandbox}</div>`;
  qbLi = `<li><span class="ok">✓</span><span>Created bill ${esc(qb.billId)} in <b>QuickBooks Online</b> (${qb.vendorNew ? 'new vendor' : 'existing vendor'}, ${(qb.lines || []).length} line${(qb.lines || []).length === 1 ? '' : 's'}${qb.attachId ? ', PDF attached' : ''})${r.row ? ' and wrote the bill number into the sheet' : ''}</span></li>`;
} else if (qb && qb.status === 'Duplicate') {
