// QuickBooks Online: one API call per run. This node works out the next call, "QuickBooks API" or
// "QuickBooks – upload PDF" makes it, and the answer comes back here until the bill is done.
// Booked: auto-approved invoices (right after reading) and invoices a manager approves.
const REALM = 'YOUR_SANDBOX_COMPANY_ID'; // sandbox company ID (not a secret)
const API = 'https://sandbox-quickbooks.api.intuit.com/v3/company/' + REALM;
const MV = 'minorversion=75';
const store = $getWorkflowStaticData('global');
const DAY_CAP = 80;

// ---- helpers ----
const qs = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
const query = (sql) => ({ url: `${API}/query?${MV}`, ctype: 'application/text', raw: sql });
const post = (path, obj) => ({ url: `${API}/${path}${path.includes('?') ? '&' : '?'}${MV}`, ctype: 'application/json', raw: JSON.stringify(obj) });
const r2 = (n) => Math.round(Number(n) * 100) / 100;
const isDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d || '') && !Number.isNaN(Date.parse(d));
const fault = (res) => {
  if (!res) return 'No answer from QuickBooks';
  if (res.error) return String(res.error.message || res.error.description || 'Request failed').slice(0, 300);
  const b = res.body || {};
  const f = b.Fault || (b.AttachableResponse && b.AttachableResponse[0] && b.AttachableResponse[0].Fault);
  if (f && f.Error && f.Error[0]) { const e = f.Error[0]; return `${e.Message || 'Error'}${e.Detail ? ': ' + e.Detail : ''}${e.code ? ' (code ' + e.code + ')' : ''}`.slice(0, 300); }
  if (res.statusCode && (res.statusCode < 200 || res.statusCode >= 300)) return `QuickBooks answered HTTP ${res.statusCode}`;
  return null;
};
const faultCode = (res) => { try { return String(((res.body || {}).Fault || {}).Error[0].code || ''); } catch (e) { return ''; } };
const rows = (res, entity) => (((res || {}).body || {}).QueryResponse || {})[entity] || [];

// ---- start of a run: which invoice, and what to do with it ----
let job = store.qboJob;
let res = null;
if ($runIndex === 0) {
  let mode = 'upload', token = null, action = null, changed = false;
  try { const d = $('Apply decision').first().json; if (d && d.token !== undefined) { mode = 'approve'; token = d.token; action = d.action; changed = !!d.changed; } } catch (e) { /* upload run */ }
  if (mode === 'upload') token = $('Check & save').first().json.token;
  job = { exec: $execution.id, mode, token, action, changed, phase: 'start', steps: 0 };
  store.qboJob = job;
} else {
  res = $input.first().json;
}
const nextUrl = job.mode === 'approve' ? $('Apply decision').first().json.nextUrl : `https://n8n.rixgpt.com/webhook/invoices/result?t=${job.token}`;
const rec = (store.inv || []).find((r) => r.token === job.token);

function finish() {
  delete store.qboJob;
  const q = rec && rec.qbo;
  let cell = '';
  if (q && q.status === 'Booked') cell = `Bill ${q.billId}${q.vendorNew ? ' (new vendor)' : ''}${q.attachId ? ', PDF attached' : ''}`;
  else if (q && q.status === 'Duplicate') cell = `Duplicate of bill ${q.billId}, not booked`;
  else if (q && q.status) cell = `${q.status}: ${String(q.error || q.note || '').slice(0, 120)}`;
  return [{ json: { qbo: 'done', mode: job.mode, nextUrl, saveSheet: !!(cell && rec && rec.row && q && q.fresh), row: rec ? rec.row : null, cell } }];
}
function fail(step, msg) { rec.qbo = Object.assign(rec.qbo || {}, { status: 'Failed', step, error: msg, at: new Date().toISOString(), fresh: true }); return finish(); }
function call(req, phase) { job.phase = phase; job.steps += 1; return [{ json: { qbo: 'call', upload: false, req } }]; }

if (!rec) return finish();
if (rec.qbo && $runIndex === 0) rec.qbo.fresh = false;
if (job.steps > 14) return fail(job.phase, 'Stopped after too many steps');

// ---- the steps ----
const cur = rec.currency || '';
const isSample = String(rec.source || '').startsWith('Sample');
switch (job.phase) {
  case 'start': {
    const book = (job.mode === 'upload' && rec.status === 'Auto-approved') || (job.mode === 'approve' && job.changed && job.action === 'approve' && rec.status === 'Approved');
    if (job.mode === 'approve' && job.changed && job.action === 'reject' && rec.status === 'Rejected') { rec.qbo = { status: 'Not booked', note: 'Sent back to the supplier, so no bill was created', fresh: true }; return finish(); }
    if (!book || (rec.qbo && ['Booked', 'Duplicate'].includes(rec.qbo.status))) return finish();
    if (!/^\d+$/.test(REALM)) { rec.qbo = { status: 'Not booked', note: 'QuickBooks is not connected yet', fresh: true }; return finish(); }
    const today = new Date().toISOString().slice(0, 10);
    if (!store.qboDay || store.qboDay.date !== today) store.qboDay = { date: today, count: 0 };
    if (store.qboDay.count >= DAY_CAP) { rec.qbo = { status: 'Not booked', note: 'The demo reached its daily QuickBooks limit', fresh: true }; return finish(); }
    store.qboDay.count += 1;
    rec.qbo = { status: 'Working', fresh: true };
    job.vendorName = (rec.supplier || 'Unknown supplier').replace(/[:\t\r\n]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 90);
    if (store.qboCo && Date.now() - store.qboCo.at < 12 * 36e5) return stepCurrency();
    return call(query('select * from Preferences'), 'prefs');
  }
  case 'prefs': {
    const e = fault(res); if (e) return fail('Read company settings', e);
    const p = rows(res, 'Preferences')[0] || {};
    const cp = p.CurrencyPrefs || {};
    store.qboCo = { home: (cp.HomeCurrency && cp.HomeCurrency.value) || 'USD', multi: !!cp.MultiCurrencyEnabled, at: Date.now() };
    return stepCurrency();
  }
  case 'currencies': {
    const e = fault(res); if (e) return fail('Check currencies', e);
    store.qboCur = { codes: rows(res, 'CompanyCurrency').filter((c) => c.Active !== false).map((c) => c.Code), at: Date.now() };
    if (store.qboCur.codes.includes(cur)) return stepRate();
    return call(post('companycurrency', { Code: cur }), 'addCurrency');
  }
  case 'addCurrency': {
    const e = fault(res); if (e) return fail(`Add ${cur} to the company`, e);
    store.qboCur.codes.push(cur);
    return stepRate();
  }
  case 'rate': {
    const r = rows(res, 'ExchangeRate')[0];
    job.rate = r && Number(r.Rate) > 0 ? Number(r.Rate) : null; // if missing, QuickBooks uses its own rate
    return stepVendor(job.vendorName);
  }
  case 'vendorFind': {
    const e = fault(res); if (e) return fail('Find the vendor', e);
    const v = rows(res, 'Vendor')[0];
    const vcur = v && v.CurrencyRef ? v.CurrencyRef.value : store.qboCo.home;
    if (v && (!store.qboCo.multi || vcur === (cur || store.qboCo.home))) { job.vendor = { id: v.Id, name: v.DisplayName, isNew: false }; return stepAccounts(); }
    if (v && !job.triedCurName) { job.triedCurName = true; job.vendorName = `${job.vendorName} (${cur})`; return stepVendor(job.vendorName); }
    const body = { DisplayName: job.vendorName, CompanyName: job.vendorName.slice(0, 100), PrintOnCheckName: job.vendorName.slice(0, 100), Notes: 'Created by the n8n AI invoice reader demo' };
    if (rec.supplierAddress) body.BillAddr = { Line1: rec.supplierAddress.slice(0, 500) };
    if (store.qboCo.multi && cur) body.CurrencyRef = { value: cur };
    job.vendorBody = body;
    return call(post('vendor', body), 'vendorCreate');
  }
  case 'vendorCreate': {
    if (faultCode(res) === '6240' && !job.renamed) { // name already used by a customer or employee
      job.renamed = true; job.vendorName = `${job.vendorName} (supplier)`.slice(0, 100);
      job.vendorBody.DisplayName = job.vendorName;
      return call(post('vendor', job.vendorBody), 'vendorCreate');
    }
    const e = fault(res); if (e) return fail('Create the vendor', e);
    const v = (res.body || {}).Vendor || {};
    job.vendor = { id: v.Id, name: v.DisplayName, isNew: true };
    return stepAccounts();
  }
  case 'accounts': {
    const e = fault(res); if (e) return fail('Read expense accounts', e);
    store.qboAcc = { list: rows(res, 'Account').filter((a) => a.Active !== false).map((a) => ({ id: a.Id, name: a.Name })), at: Date.now() };
    return stepDupe();
  }
  case 'dupe': {
    const e = fault(res); if (e) return fail('Check for duplicates', e);
    const hit = rows(res, 'Bill').find((b) => b.VendorRef && String(b.VendorRef.value) === String(job.vendor.id));
    if (hit) {
      rec.qbo = { status: 'Duplicate', billId: hit.Id, docNumber: hit.DocNumber, vendor: job.vendor.name, total: hit.TotalAmt, currency: hit.CurrencyRef ? hit.CurrencyRef.value : store.qboCo.home, created: hit.MetaData ? hit.MetaData.CreateTime : '', fresh: true, at: new Date().toISOString() };
      return finish();
    }
    return stepBill();
  }
  case 'bill': {
    const e = fault(res); if (e) return fail('Create the bill', e);
    const b = (res.body || {}).Bill || {};
    const accName = (id) => ((store.qboAcc.list.find((a) => a.id === id) || {}).name || id);
    rec.qbo = {
      status: 'Booked', fresh: true, at: new Date().toISOString(), billId: b.Id, docNumber: b.DocNumber, txnDate: b.TxnDate, dueDate: b.DueDate,
      total: b.TotalAmt, balance: b.Balance, currency: b.CurrencyRef ? b.CurrencyRef.value : store.qboCo.home, rate: b.ExchangeRate || null, home: store.qboCo.home,
      vendor: job.vendor.name, vendorId: job.vendor.id, vendorNew: job.vendor.isNew, note: job.billNote || '',
      lines: (b.Line || []).filter((l) => l.DetailType === 'AccountBasedExpenseLineDetail').slice(0, 12).map((l) => ({ d: String(l.Description || '').slice(0, 90), a: l.Amount, acc: accName(l.AccountBasedExpenseLineDetail && l.AccountBasedExpenseLineDetail.AccountRef ? l.AccountBasedExpenseLineDetail.AccountRef.value : '') })),
      created: b.MetaData ? b.MetaData.CreateTime : '',
    };
    return stepAttach();
  }
  case 'attach': {
    const e = fault(res);
    if (e) rec.qbo.attachError = e;
    else { const a = ((res.body || {}).AttachableResponse || [])[0] || {}; rec.qbo.attachId = a.Attachable ? a.Attachable.Id : null; rec.qbo.attachName = a.Attachable ? a.Attachable.FileName : ''; }
    rec.qbo.fresh = true;
    return finish();
  }
  default:
    return finish();
}

// ---- step builders ----
function stepCurrency() {
  const home = store.qboCo.home;
  if (!cur || cur === home) return stepVendor(job.vendorName);
  if (!store.qboCo.multi) { rec.qbo = { status: 'Not booked', note: `This QuickBooks company works in ${home} only (multicurrency is off), so a ${cur} invoice was not booked`, fresh: true }; return finish(); }
  if (store.qboCur && Date.now() - store.qboCur.at < 12 * 36e5 && store.qboCur.codes.includes(cur)) return stepRate();
  return call(query('select * from CompanyCurrency'), 'currencies');
}
function stepRate() {
  const d = isDate(rec.invoiceDate) && rec.invoiceDate <= new Date().toISOString().slice(0, 10) ? rec.invoiceDate : new Date().toISOString().slice(0, 10);
  return call(query(`select * from ExchangeRate where SourceCurrencyCode = '${qs(cur)}' and AsOfDate = '${d}'`), 'rate');
}
function stepVendor(name) { return call(query(`select * from Vendor where DisplayName = '${qs(name)}'`), 'vendorFind'); }
function stepAccounts() {
  if (store.qboAcc && Date.now() - store.qboAcc.at < 12 * 36e5 && store.qboAcc.list.length) return stepDupe();
  return call(query("select * from Account where AccountType = 'Expense' maxresults 200"), 'accounts');
}
function docNumber() {
  const base = String(rec.invoiceNumber || '').replace(/\s+/g, '').slice(0, 21);
  if (!base) return '';
  return isSample ? `${base.slice(0, 15)}-${job.token.slice(0, 4).toUpperCase()}` : base; // sample runs get a suffix so each visitor gets a fresh bill
}
function stepDupe() {
  const doc = docNumber();
  if (!doc || isSample) return stepBill();
  return call(query(`select * from Bill where DocNumber = '${qs(doc)}'`), 'dupe');
}
function account(category) {
  const MAP = { 'Software & hosting': ['Dues & Subscriptions', 'Office Expenses'], 'Office supplies': ['Office Expenses', 'Supplies', 'Stationery & Printing'], Marketing: ['Advertising', 'Promotional'], 'Professional services': ['Legal & Professional Fees'], Travel: ['Travel'], Meals: ['Meals and Entertainment', 'Travel Meals'], Utilities: ['Utilities'], Hardware: ['Office Expenses', 'Supplies'] };
  const list = store.qboAcc.list;
  for (const n of [...(MAP[category] || []), 'Uncategorized Expense']) { const a = list.find((x) => x.name.toLowerCase() === n.toLowerCase()); if (a) return a.id; }
  return list[0] ? list[0].id : null;
}
function stepBill() {
  const accId = account(rec.category);
  if (!accId) return fail('Pick an expense account', 'No active expense account found in the company');
  const line = (amount, desc) => ({ DetailType: 'AccountBasedExpenseLineDetail', Amount: r2(amount), Description: String(desc).slice(0, 4000), AccountBasedExpenseLineDetail: { AccountRef: { value: accId } } });
  const tax = rec.tax > 0 ? r2(rec.tax) : 0;
  let lines = rec.items.map((i) => {
    const amt = i.amount ?? (i.quantity !== null && i.unit_price !== null ? i.quantity * i.unit_price : null);
    const qty = i.quantity !== null && i.unit_price !== null && !(i.quantity === 1) ? ` (${i.quantity} × ${Number(i.unit_price).toFixed(2)})` : '';
    return amt === null ? null : { amt: r2(amt), desc: (i.description || 'Item') + qty };
  }).filter(Boolean);
  const notes = [];
  let sum = r2(lines.reduce((a, l) => a + l.amt, 0) + tax);
  const total = rec.total !== null ? r2(rec.total) : null;
  if (!lines.length || lines.some((l) => l.amt <= 0) || (total !== null && sum - total > 0.01)) {
    const net = total !== null ? r2(total - tax) : r2(rec.subtotal || 0);
    lines = [{ amt: net, desc: (rec.summary || 'Invoice') + ' (line detail is in the attached PDF)' }];
    sum = r2(net + tax);
  }
  const out = lines.map((l) => line(l.amt, l.desc));
  if (tax) out.push(line(tax, `Tax as printed on the invoice${rec.taxRate ? ' (' + rec.taxRate + '%)' : ''}`));
  if (total !== null && total - sum > 0.01) { out.push(line(total - sum, 'Difference to the printed total, accepted at approval')); notes.push(`The line items did not add up to the printed total; ${r2(total - sum).toFixed(2)} was booked as a separate line so the bill matches what the supplier asks for.`); }
  job.billNote = notes.join(' ');
  const decided = rec.decidedAt ? new Date(rec.decidedAt).toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'medium', timeStyle: 'short' }) + ' (UK)' : '';
  const bill = {
    VendorRef: { value: job.vendor.id },
    Line: out,
    PrivateNote: [`Booked by the n8n AI invoice reader demo (${isSample ? 'sample invoice' : 'uploaded file'} ${rec.fileName}).`, rec.status === 'Approved' ? `Approved by a manager on ${decided}.` : 'Auto-approved: under 500 and all checks passed.', rec.po ? `PO ${rec.po}.` : '', job.billNote].filter(Boolean).join(' ').slice(0, 4000),
  };
  const doc = docNumber(); if (doc) bill.DocNumber = doc;
  if (isDate(rec.invoiceDate)) bill.TxnDate = rec.invoiceDate;
  if (isDate(rec.dueDate) && (!bill.TxnDate || rec.dueDate >= bill.TxnDate)) bill.DueDate = rec.dueDate;
  if (store.qboCo.multi && cur && cur !== store.qboCo.home) { bill.CurrencyRef = { value: cur }; if (job.rate) bill.ExchangeRate = job.rate; }
  return call(post('bill', bill), 'bill');
}
function stepAttach() {
  // The file: rebuilt for sample invoices, or the uploaded file when it is booked straight after reading.
  // Uploaded files that wait for approval are not kept by this public demo, so their bill has no PDF.
  let b64 = null, mime = rec.mime || 'application/pdf';
  if (job.mode === 'upload') { try { b64 = $('Prepare upload').first().json.geminiBody.contents[0].parts[1].inline_data.data; } catch (e) { b64 = null; } }
  else if (isSample) { const s = SAMPLES[String(rec.source).replace(/\D/g, '')]; if (s) { b64 = makePdf(s).toString('base64'); mime = 'application/pdf'; } }
  if (!b64) { rec.qbo.attachNote = 'The uploaded file is not kept while it waits for approval in this public demo, so the bill has no PDF attached.'; return finish(); }
  const fileName = String(rec.fileName || 'invoice.pdf').replace(/["\r\n]/g, '').slice(0, 80);
  const meta = JSON.stringify({ AttachableRef: [{ EntityRef: { type: 'Bill', value: rec.qbo.billId } }], FileName: fileName, ContentType: mime, Note: 'Original invoice, attached by the n8n demo' });
  job.phase = 'attach'; job.steps += 1;
  // two multipart parts: file_metadata_01 (JSON) and file_content_01 (the file); the upload node builds the request
  return [{ json: { qbo: 'call', upload: true, req: { url: `${API}/upload?${MV}` } }, binary: {
    meta: { data: Buffer.from(meta, 'utf8').toString('base64'), mimeType: 'application/json', fileName: 'attachment.json', fileExtension: 'json' },
    file: { data: b64, mimeType: mime, fileName, fileExtension: (fileName.split('.').pop() || 'pdf').toLowerCase() },
  } }];
}
